package org.brightstats.desktop;
import java.util.Arrays;
import javafx.geometry.Insets;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import org.brightstats.stats.CopulaRegression;
final class CopulaPlots {
 private CopulaPlots(){}
 static void add(TabPane tabs,CopulaRegression.Fit fit){double[] predicted=fit.predictions(),residual=fit.residuals(),sorted=residual.clone();Arrays.sort(sorted);int count=Math.min(5000,residual.length);NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel("Augmented fitted outcome");x.setForceZeroInRange(false);y.setLabel("Augmented residual");y.setForceZeroInRange(false);ScatterChart<Number,Number> scatter=new ScatterChart<>(x,y);scatter.setTitle("Residuals versus fitted values");scatter.setAnimated(false);scatter.setMinHeight(430);var points=new XYChart.Series<Number,Number>();points.setName("Analysis rows");NumberAxis qx=new NumberAxis(),qy=new NumberAxis();qx.setLabel("Standard normal quantile");qy.setLabel("Sorted augmented residual");qx.setForceZeroInRange(false);qy.setForceZeroInRange(false);LineChart<Number,Number> qq=new LineChart<>(qx,qy);qq.setTitle("Augmented residual Q–Q diagnostic");qq.setAnimated(false);qq.setCreateSymbols(false);qq.setMinHeight(430);var quantiles=new XYChart.Series<Number,Number>();quantiles.setName("Empirical residual quantiles");var normal=new org.apache.commons.math3.distribution.NormalDistribution();for(int index=0;index<count;index++){int row=(int)Math.round(index*(residual.length-1.0)/(count-1));points.getData().add(new XYChart.Data<>(predicted[row],residual[row]));double z=normal.inverseCumulativeProbability((row+.5)/residual.length);quantiles.getData().add(new XYChart.Data<>(z,sorted[row]));}scatter.getData().add(points);qq.getData().add(quantiles);Label guidance=new Label("Descriptive augmented-residual diagnostics do not test the unobserved structural error's normality or establish identification. "+(count<residual.length?"Plot presentation uses 5,000 evenly spaced source rows/ordered residuals; all rows remain in estimation and numeric results.":"All analysis rows are plotted."));guidance.setWrapText(true);VBox charts=new VBox(12,guidance,scatter,qq);charts.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(charts);scroll.setFitToWidth(true);Tab tab=new Tab("Copula diagnostic plots",scroll);tab.setClosable(false);tabs.getTabs().add(tab);}
}
